 'Не является универсальным средством салона. Для неизвестного пластика/текстиля автоматический выбор запрещён.')
on conflict(brand,name) do update set
 category=excluded.category,intended_surfaces=excluded.intended_surfaces,prohibited_surfaces=excluded.prohibited_surfaces,
 dilution=excluded.dilution,application_method=excluded.application_method,dwell_time=excluded.dwell_time,
 follow_up=excluded.follow_up,warnings=excluded.warnings,shop_url=excluded.shop_url,
 verification_status=excluded.verification_status,source_note=excluded.source_note,active=true,
 use_role=excluded.use_role,risk_level=excluded.risk_level,approval_required=excluded.approval_required,
 technology_note=excluded.technology_note,updated_at=now();

update public.chemicals set use_role='escalation',risk_level='caution',approval_required=false,
 technology_note='Щелочной усиленный очиститель. Для обычного текстиля SIR сначала предпочитает более щадящую подтверждённую схему. На деликатных материалах/потолке не выбирать автоматически.',updated_at=now()
where brand='Koch-Chemie' and name='Green Star';

update public.chemicals set use_role='exterior',risk_level='low',approval_required=false where name in ('NanoMagicShampoo','CARPRO ReTyre','CARPRO DarkSide');
update public.chemicals set use_role='exterior_care',risk_level='caution',approval_required=false where name='Plast Star siliconölfrei';
